static const VnFont vnFont17 = {23, 234, vnFont17_glyphs, vnFont17_bitmap};

static inline uint16_t vnNextUtf8(const char*& p) {
  uint8_t b0 = (uint8_t)*p++;
  if (b0 < 0x80) return b0;
  if ((b0 & 0xE0) == 0xC0) {
    uint8_t b1 = (uint8_t)*p;
    if (!b1) return '?';
    p++;
    return ((b0 & 0x1F) << 6) | (b1 & 0x3F);
  }
  if ((b0 & 0xF0) == 0xE0) {
    uint8_t b1 = (uint8_t)p[0], b2 = (uint8_t)p[1];
    if (!b1 || !b2) return '?';
    p += 2;
    return ((b0 & 0x0F) << 12) | ((b1 & 0x3F) << 6) | (b2 & 0x3F);
  }
  if ((b0 & 0xF8) == 0xF0) {
    for (int k = 0; k < 3 && *p; k++) p++;
  }
  return '?';
}

static inline const VnGlyph* vnFindGlyph(const VnFont& f, uint16_t cp) {
  if (cp == 0x2018 || cp == 0x2019) cp = 0x0027;
  else if (cp == 0x201C || cp == 0x201D) cp = '"';
  int lo = 0, hi = (int)f.glyphCount - 1;
  while (lo <= hi) {
    int mid = (lo + hi) >> 1;
    uint16_t mcp = pgm_read_word(&f.glyphs[mid].codepoint);
    if (mcp == cp) return &f.glyphs[mid];
    if (mcp < cp) lo = mid + 1;
    else hi = mid - 1;
  }
  return nullptr;
}

static inline int vnTextWidth(const VnFont& f, const char* s) {
  if (!s) return 0;
  int w = 0;
  while (*s) {
    uint16_t cp = vnNextUtf8(s);
    const VnGlyph* g = vnFindGlyph(f, cp);
    if (g) w += pgm_read_byte(&g->xAdv);
  }
  return w;
}

static inline uint16_t vnBlend565(uint16_t fg, uint16_t bg, uint8_t alpha4) {
  if (alpha4 == 0) return bg;
  if (alpha4 >= 15) return fg;
  uint16_t fr = (fg >> 11) & 0x1F, fg_ = (fg >> 5) & 0x3F, fb = fg & 0x1F;
  uint16_t br = (bg >> 11) & 0x1F, bg_ = (bg >> 5) & 0x3F, bb = bg & 0x1F;
  uint16_t inv = 15 - alpha4;
  uint16_t r = (fr * alpha4 + br * inv + 7) / 15;
  uint16_t g = (fg_ * alpha4 + bg_ * inv + 7) / 15;
  uint16_t b = (fb * alpha4 + bb * inv + 7) / 15;
  return (r << 11) | (g << 5) | b;
}

static inline void vnDrawText(Adafruit_GFX* tft, const VnFont& f, int x, int y, const char* s, uint16_t fg, uint16_t bg) {
  if (!tft || !s) return;
  uint16_t pixBuf[24 * 24];
  int curX = x;
  while (*s) {
    uint16_t cp = vnNextUtf8(s);
    const VnGlyph* g = vnFindGlyph(f, cp);
    if (!g) g = vnFindGlyph(f, '?');
    if (!g) continue;
    uint8_t w = pgm_read_byte(&g->w);
    uint8_t h = pgm_read_byte(&g->h);
    int8_t xo = (int8_t)pgm_read_byte(&g->xOff);
    int8_t yo = (int8_t)pgm_read_byte(&g->yOff);
    uint8_t adv = pgm_read_byte(&g->xAdv);
    uint32_t off = pgm_read_dword(&g->offset);

    if (w > 0 && h > 0 && (int)w * (int)h <= (int)(sizeof(pixBuf) / sizeof(pixBuf[0]))) {
      int total = w * h;
      for (int i = 0; i < total; i++) {
        uint8_t packed = pgm_read_byte(&f.bitmap[off + (i >> 1)]);
        uint8_t a4 = (i & 1) ? (packed & 0x0F) : (packed >> 4);
        pixBuf[i] = vnBlend565(fg, bg, a4);
      }
      tft->drawRGBBitmap(curX + xo, y + yo, pixBuf, w, h);
    }
    curX += adv;
  }
}

